  ('en-c4-grammar', 'ingilis-dili', 'Qayda: Sual və inkar', 'Sual (do/does/did) və inkar (don''t/doesn''t/didn''t) cümlələri.', 15),
  ('en-c4-vocab', 'ingilis-dili', 'Lüğət: Sual sözləri', '6 sual sözü: what, where, when, who, why, how.', 16),
  ('en-c4-listening', 'ingilis-dili', 'Dinləmə: Sual və inkar', 'Sual və inkar cümlələrini dinlə və düzgün mənanı seç.', 17),
  ('en-c4-reading', 'ingilis-dili', 'Oxu: An interview', 'Qısa müsahibəni oxu və suallara cavab ver (sual-cavab).', 18),
  ('en-c4-writing', 'ingilis-dili', 'Yazı: Sual və inkar', 'Sözlərdən düzgün sual və inkar cümləsi qur.', 19),
  ('en-c5-grammar', 'ingilis-dili', 'Qayda: Əvəzliklər', 'Şəxs (I, you, he...) və yiyəlik (my, your, his...) əvəzlikləri.', 20),
  ('en-c5-vocab', 'ingilis-dili', 'Lüğət: Əvəzliklər', 'Şəxs və yiyəlik əvəzlikləri: I/he/she/we/they, my/your/her...', 21),
  ('en-c5-listening', 'ingilis-dili', 'Dinləmə: Əvəzliklər', 'Əvəzlikli cümlələri dinlə və düzgün mənanı seç.', 22),
