  ('en-c6-grammar', 'ingilis-dili', 'Qayda: Artikllar (a / an / the)', 'Qeyri-müəyyən (a/an) və müəyyən (the) artikllar.', 25),
  ('en-c6-vocab', 'ingilis-dili', 'Lüğət: Əşyalar', '8 yeni isim: orange, egg, umbrella, elephant, banana, pen, car, box.', 26),
