  ('en-nouns', 'ingilis-dili', 'İsimlər (Nouns)', 'İsim nədir, cəm forması, sayıla bilən və sayıla bilməyən isimlər.', 31),
  ('en-vocab', 'ingilis-dili', 'Söz ehtiyatı (Vocabulary)', 'Gündəlik həyatla bağlı mövzular: ailə, məktəb, təbiət, qida, şəhər və hobbilər.', 32)
insert into lessons (id, unit_id, title, intro, visual, sections, sort_order) values
  ('pron-rule', 'en-c5-grammar', 'Əvəzliklər qaydası', 'İsim əvəzinə işlənən sözlər — əvəzliklər. Gəl öyrənək!', null, '[{"heading":"Şəxs əvəzlikləri","body":"I (mən), you (sən/siz), he (o — kişi), she (o — qadın), it (o — əşya/heyvan), we (biz), they (onlar). Cümlədə isim əvəzinə işlənir."},{"heading":"Yiyəlik əvəzlikləri","body":"my (mənim), your (sənin), his (onun — kişi), her (onun — qadın), its (onun), our (bizim), their (onların). İsimdən əvvəl gəlir: my book, her cat."},{"heading":"Nə vaxt he / she / it?","body":"Kişi üçün he, qadın üçün she, əşya/heyvan üçün it. Ali → he, Nigar → she, the cat → it."}]'::jsonb, 0),
  ('pron-vocab', 'en-c5-vocab', 'Əvəzliklər (sözlər)', 'Əvəzliklərin mənasını öyrənək.', null, '[{"heading":"Şəxs əvəzlikləri","body":"I — mən · you — sən/siz · he — o (kişi) · she — o (qadın) · it — o (əşya) · we — biz · they — onlar"},{"heading":"Yiyəlik əvəzlikləri","body":"my — mənim · your — sənin · his — onun (kişi) · her — onun (qadın) · our — bizim · their — onların"}]'::jsonb, 0),
  ('pron-listen', 'en-c5-listening', 'Dinlə və seç: əvəzliklər', 'Cümləni dinlə və düzgün cavabı seç.', null, '[{"heading":"Necə işləyir?","body":"«Dinlə» düyməsinə bas, cümləni eşit və düzgün variantı seç. İstədiyin qədər təkrar dinlə."}]'::jsonb, 0),
  ('pron-read', 'en-c5-reading', 'Reading: My family', 'Qısa mətni oxu və suallara cavab ver.', null, '[{"heading":"Read the text (Mətni oxu)","body":"This is my family. My father is a doctor. He works at a hospital. My mother is a teacher. She works at a school. I have a sister. Her name is Aysel. She is nine. We have a cat. It is black and white. Its name is Pamuk. We love our cat."},{"heading":"İpucu","body":"Sualı oxu, cavabı mətndə tap. Lazım olsa mətnə yenidən bax."}]'::jsonb, 0),
  ('pron-write', 'en-c5-writing', 'Cümlə qur: əvəzliklər', 'Sözləri düzgün sıraya düz və cümlə qur.', null, '[{"heading":"Necə işləyir?","body":"Sözlərə sıra ilə bas. Cümlə əvəzliklə başlaya bilər: He is..., They are..., This is my..."}]'::jsonb, 0),
  ('art-rule', 'en-c6-grammar', 'Artikllar qaydası', 'a, an, the — İngiliscə artikllar. Nə vaxt hansını işlətməli?', null, '[{"heading":"a / an nə üçündür?","body":"Tək, sayıla bilən isimdən əvvəl: a book, a dog. Samitlə başlayan sözdən əvvəl ''a'', saitlə (a,e,i,o,u) başlayan sözdən əvvəl ''an'': an apple, an egg, an umbrella."},{"heading":"the nə üçündür?","body":"Konkret, məlum əşya üçün: the sun, the book (masanın üstündəki). Həm tək, həm cəm ilə işlənir."},{"heading":"Nə vaxt artikl yox?","body":"Cəm ümumi isimlərdə artikl işlənmir: I like apples. Dogs are friendly."}]'::jsonb, 0),
  ('art-vocab', 'en-c6-vocab', 'Əşyalar (8 söz)', '8 yeni isim öyrənək və a/an ilə işlədək.', null, '[{"heading":"Yeni sözlər (8 isim)","body":"orange — portağal · egg — yumurta · umbrella — çətir · elephant — fil · banana — banan · pen — qələm · car — maşın · box — qutu"},{"heading":"Məsləhət","body":"Saitlə başlayanlar ''an'' alır: an orange, an egg, an umbrella, an elephant. Samitlə başlayanlar ''a'': a banana, a pen, a car, a box."}]'::jsonb, 0),
  ('art-listen', 'en-c6-listening', 'Dinlə və seç: əşyalar', 'Cümləni dinlə və düzgün cavabı seç.', null, '[{"heading":"Necə işləyir?","body":"«Dinlə» düyməsinə bas, cümləni eşit və düzgün variantı seç. İstədiyin qədər təkrar dinlə."}]'::jsonb, 0),
  ('art-read', 'en-c6-reading', 'Reading: A day at the zoo', 'Qısa mətni oxu və suallara cavab ver.', null, '[{"heading":"Read the text (Mətni oxu)","body":"Today we are at the zoo. Look! There is an elephant. It is very big. There is a lion too. The lion is sleeping. I can see a monkey. The monkey is eating a banana. Near the water there is a bird. It is an eagle. I like the zoo very much."},{"heading":"İpucu","body":"Sualı oxu, cavabı mətndə tap. Lazım olsa mətnə yenidən bax."}]'::jsonb, 0),
  ('art-write', 'en-c6-writing', 'Cümlə qur: artikllar', 'Sözləri düzgün sıraya düz və cümlə qur.', null, '[{"heading":"Necə işləyir?","body":"Sözlərə sıra ilə bas. Saitlə başlayan isimdən əvvəl ''an'', samitlə başlayandan əvvəl ''a''."}]'::jsonb, 0)
